import { cn } from "@/lib/utils";

/**
 * Ecomsia hexagonal brand badge.
 * Pure SVG, no runtime dependency — drop it anywhere.
 */
export function HexBadge({ className }: { className?: string }) {
  return (
    <svg
      viewBox="0 0 100 100"
      role="img"
      aria-label="Ecomsia"
      className={cn("size-9", className)}
    >
      <rect width="100" height="100" rx="22" fill="#0b1220" />
      <path
        d="M50 12 L83 31 L83 69 L50 88 L17 69 L17 31 Z"
        fill="none"
        stroke="var(--ecomsia-accent, #0ff1cf)"
        strokeWidth={5}
        strokeLinejoin="round"
      />
      <g fill="var(--ecomsia-ice, #e9fdff)">
        <rect x="41" y="35" width="7" height="30" rx="1.6" />
        <rect x="41" y="35" width="18" height="6.5" rx="1.6" />
        <rect x="41" y="46.75" width="15" height="6.5" rx="1.6" />
        <rect x="41" y="58.5" width="18" height="6.5" rx="1.6" />
      </g>
    </svg>
  );
}

import { cn } from "@/lib/utils";

/**
 * Horizontal Ecomsia lockup (mark + wordmark + tagline).
 * Place `assets/logo-white.png` where your bundler can resolve the import.
 */
export function LogoLockup({
  tagline = "Agence Digitale",
  className,
}: {
  tagline?: string | null;
  className?: string;
}) {
  return (
    <span className={cn("inline-flex items-center gap-2", className)}>
      <img src="/logo-white.png" alt="Ecomsia" width={36} height={36} className="size-9" />
      <span className="flex flex-col leading-none">
        <span className="text-xl font-bold tracking-tight text-white">ECOMSIA</span>
        {tagline ? (
          <span className="mt-1 text-[10px] font-medium tracking-[0.35em] text-white/60">
            {tagline.toUpperCase()}
          </span>
        ) : null}
      </span>
    </span>
  );
}
